export type EasingFunction = (t: number) => number;

export type EasingName =
  | 'linear'
  | 'easeInQuad'
  | 'easeOutQuad'
  | 'easeInOutQuad'
  | 'easeOutCubic'
  | 'easeInOutCubic'
  | 'easeOutExpo'
  | 'easeOutBack';

const BACK_OVERSHOOT = 1.70158;

/** Easing curves used by camera transitions; every curve maps 0 -> 0 and 1 -> 1. */
export const EASINGS: Readonly<Record<EasingName, EasingFunction>> = {
  linear: (t) => t,
  easeInQuad: (t) => t * t,
  easeOutQuad: (t) => t * (2 - t),
  easeInOutQuad: (t) => (t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2),
  easeOutCubic: (t) => 1 - (1 - t) ** 3,
  easeInOutCubic: (t) => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2),
  easeOutExpo: (t) => (t >= 1 ? 1 : 1 - 2 ** (-10 * t)),
  easeOutBack: (t) => 1 + (BACK_OVERSHOOT + 1) * (t - 1) ** 3 + BACK_OVERSHOOT * (t - 1) ** 2,
};

export const DEFAULT_EASING: EasingName = 'easeInOutCubic';

export function clamp01(value: number): number {
  if (!Number.isFinite(value)) return 0;
  if (value <= 0) return 0;
  return value >= 1 ? 1 : value;
}

/** Accepts a named curve, a custom function or nothing and always returns a curve. */
export function resolveEasing(
  easing?: EasingName | EasingFunction,
  fallback: EasingName = DEFAULT_EASING,
): EasingFunction {
  if (typeof easing === 'function') return easing;
  if (typeof easing === 'string' && easing in EASINGS) return EASINGS[easing];
  return EASINGS[fallback];
}
