import type { Vec3 } from '../contracts/math';

export interface ScalarSpringState {
  velocity: number;
}

export interface Vec3SpringState {
  velocity: Vec3;
}

const EPSILON = 1e-6;

export function createScalarSpringState(velocity = 0): ScalarSpringState {
  return { velocity };
}

export function createVec3SpringState(): Vec3SpringState {
  return { velocity: { x: 0, y: 0, z: 0 } };
}

/** Clamps a frame delta so a stalled tab or a breakpoint cannot teleport the camera. */
export function clampDeltaSeconds(deltaSeconds: number, maxStep = 0.1): number {
  if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return 0;
  if (!Number.isFinite(maxStep) || maxStep <= 0) return deltaSeconds;
  return Math.min(deltaSeconds, maxStep);
}

/**
 * Frame-rate independent blend factor: the share of the remaining distance to
 * cover during `deltaSeconds` for an exponential decay with the given time
 * constant. Several small steps give the same result as one large step.
 */
export function dampFactor(smoothTime: number, deltaSeconds: number): number {
  if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return 0;
  if (!Number.isFinite(smoothTime) || smoothTime <= EPSILON) return 1;
  return 1 - Math.exp(-deltaSeconds / smoothTime);
}

export function damp(current: number, target: number, smoothTime: number, deltaSeconds: number): number {
  return current + (target - current) * dampFactor(smoothTime, deltaSeconds);
}

export function dampVec3(current: Vec3, target: Vec3, smoothTime: number, deltaSeconds: number): Vec3 {
  const factor = dampFactor(smoothTime, deltaSeconds);
  return {
    x: current.x + (target.x - current.x) * factor,
    y: current.y + (target.y - current.y) * factor,
    z: current.z + (target.z - current.z) * factor,
  };
}

/** Normalises an angle to (-PI, PI]. */
export function wrapAngle(radians: number): number {
  if (!Number.isFinite(radians)) return 0;
  const twoPi = Math.PI * 2;
  let angle = (radians + Math.PI) % twoPi;
  if (angle <= 0) angle += twoPi;
  return angle - Math.PI;
}

/** Damps yaw-like values along the shortest arc instead of unwinding the long way. */
export function dampAngle(current: number, target: number, smoothTime: number, deltaSeconds: number): number {
  return current + wrapAngle(target - current) * dampFactor(smoothTime, deltaSeconds);
}

/**
 * Critically damped spring step: converges without overshoot and keeps its
 * velocity between frames, which is what makes a follow camera feel weighty
 * instead of rubbery when the desired pose jumps around.
 */
export function smoothDamp(
  current: number,
  target: number,
  state: ScalarSpringState,
  smoothTime: number,
  deltaSeconds: number,
  maxSpeed = Number.POSITIVE_INFINITY,
): number {
  if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return current;

  const time = Math.max(EPSILON, smoothTime);
  const omega = 2 / time;
  const x = omega * deltaSeconds;
  const decay = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x);
  const maxChange = maxSpeed * time;
  const change = Math.min(Math.max(current - target, -maxChange), maxChange);
  const clampedTarget = current - change;
  const temp = (state.velocity + omega * change) * deltaSeconds;

  state.velocity = (state.velocity - omega * temp) * decay;
  let output = clampedTarget + (change + temp) * decay;

  if ((target - current > 0) === (output > target)) {
    output = target;
    state.velocity = 0;
  }

  return output;
}

/** Vector flavour of {@link smoothDamp}; `maxSpeed` limits the whole vector, not each axis. */
export function smoothDampVec3(
  current: Vec3,
  target: Vec3,
  state: Vec3SpringState,
  smoothTime: number,
  deltaSeconds: number,
  maxSpeed = Number.POSITIVE_INFINITY,
): Vec3 {
  if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return { ...current };

  const time = Math.max(EPSILON, smoothTime);
  const omega = 2 / time;
  const x = omega * deltaSeconds;
  const decay = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x);

  let changeX = current.x - target.x;
  let changeY = current.y - target.y;
  let changeZ = current.z - target.z;

  const maxChange = maxSpeed * time;
  const changeLength = Math.hypot(changeX, changeY, changeZ);
  if (Number.isFinite(maxChange) && changeLength > maxChange && changeLength > EPSILON) {
    const scale = maxChange / changeLength;
    changeX *= scale;
    changeY *= scale;
    changeZ *= scale;
  }

  const velocity = state.velocity;
  const tempX = (velocity.x + omega * changeX) * deltaSeconds;
  const tempY = (velocity.y + omega * changeY) * deltaSeconds;
  const tempZ = (velocity.z + omega * changeZ) * deltaSeconds;

  velocity.x = (velocity.x - omega * tempX) * decay;
  velocity.y = (velocity.y - omega * tempY) * decay;
  velocity.z = (velocity.z - omega * tempZ) * decay;

  let outX = current.x - changeX + (changeX + tempX) * decay;
  let outY = current.y - changeY + (changeY + tempY) * decay;
  let outZ = current.z - changeZ + (changeZ + tempZ) * decay;

  const toTargetX = target.x - current.x;
  const toTargetY = target.y - current.y;
  const toTargetZ = target.z - current.z;
  const overshootX = outX - target.x;
  const overshootY = outY - target.y;
  const overshootZ = outZ - target.z;

  if (toTargetX * overshootX + toTargetY * overshootY + toTargetZ * overshootZ > 0) {
    outX = target.x;
    outY = target.y;
    outZ = target.z;
    velocity.x = 0;
    velocity.y = 0;
    velocity.z = 0;
  }

  return { x: outX, y: outY, z: outZ };
}
