import type { Vec3 } from '../contracts/math';

/** Everything a camera needs per frame, free of any renderer dependency. */
export interface CameraPose {
  position: Vec3;
  target: Vec3;
  fov: number;
}

export const DEFAULT_CAMERA_FOV = 55;

export function createCameraPose(position: Vec3, target: Vec3, fov: number = DEFAULT_CAMERA_FOV): CameraPose {
  return { position: { ...position }, target: { ...target }, fov };
}

export function cloneCameraPose(pose: CameraPose): CameraPose {
  return { position: { ...pose.position }, target: { ...pose.target }, fov: pose.fov };
}

export function lerpVec3(from: Vec3, to: Vec3, t: number): Vec3 {
  return {
    x: from.x + (to.x - from.x) * t,
    y: from.y + (to.y - from.y) * t,
    z: from.z + (to.z - from.z) * t,
  };
}

/** `t` is intentionally not clamped so overshooting curves keep their punch. */
export function lerpCameraPose(from: CameraPose, to: CameraPose, t: number): CameraPose {
  return {
    position: lerpVec3(from.position, to.position, t),
    target: lerpVec3(from.target, to.target, t),
    fov: from.fov + (to.fov - from.fov) * t,
  };
}

/** Worst-case gap between two poses; used for arrival checks. */
export function cameraPoseDistance(a: CameraPose, b: CameraPose): number {
  return Math.max(
    Math.hypot(a.position.x - b.position.x, a.position.y - b.position.y, a.position.z - b.position.z),
    Math.hypot(a.target.x - b.target.x, a.target.y - b.target.y, a.target.z - b.target.z),
  );
}
