import type { CameraPose } from './CameraPose';
import { cloneCameraPose, lerpCameraPose } from './CameraPose';
import type { EasingFunction, EasingName } from './Easing';
import { clamp01, resolveEasing } from './Easing';

export interface CameraTransitionOptions {
  durationSeconds?: number;
  easing?: EasingName | EasingFunction;
}

export const DEFAULT_TRANSITION_SECONDS = 0.75;

/**
 * Timed blend from a frozen start pose toward a destination that may keep
 * moving while the transition plays (the ball is still rolling, the hole intro
 * pans, the player switches). A non-positive duration is an instant cut.
 */
export class CameraTransition {
  private from: CameraPose | null = null;
  private duration = 0;
  private elapsed = 0;
  private ease: EasingFunction = resolveEasing();

  get isActive(): boolean {
    return this.from !== null;
  }

  get progress(): number {
    if (this.from === null || this.duration <= 0) return 1;
    return clamp01(this.elapsed / this.duration);
  }

  start(from: CameraPose, options: CameraTransitionOptions = {}): void {
    const duration = options.durationSeconds ?? DEFAULT_TRANSITION_SECONDS;
    this.ease = resolveEasing(options.easing);
    this.elapsed = 0;

    if (!Number.isFinite(duration) || duration <= 0) {
      this.from = null;
      this.duration = 0;
      return;
    }

    this.from = cloneCameraPose(from);
    this.duration = duration;
  }

  cancel(): void {
    this.from = null;
    this.duration = 0;
    this.elapsed = 0;
  }

  update(deltaSeconds: number, destination: CameraPose): CameraPose {
    if (this.from === null) return cloneCameraPose(destination);
    if (Number.isFinite(deltaSeconds) && deltaSeconds > 0) this.elapsed += deltaSeconds;

    const t = this.progress;
    const pose = lerpCameraPose(this.from, destination, this.ease(t));
    if (t >= 1) this.cancel();
    return pose;
  }
}
