import * as THREE from 'three';
import type { CameraPose } from './CameraPose';
import { createCameraPose } from './CameraPose';

/** Writes a smoothed pose onto a Three.js perspective camera. */
export function applyCameraPose(camera: THREE.PerspectiveCamera, pose: CameraPose): void {
  camera.position.set(pose.position.x, pose.position.y, pose.position.z);
  camera.lookAt(pose.target.x, pose.target.y, pose.target.z);

  if (Number.isFinite(pose.fov) && Math.abs(camera.fov - pose.fov) > 1e-4) {
    camera.fov = pose.fov;
    camera.updateProjectionMatrix();
  }
}

/** Reads the current pose back; `distance` decides where the look-at target lands. */
export function readCameraPose(camera: THREE.PerspectiveCamera, distance = 1): CameraPose {
  const forward = new THREE.Vector3();
  camera.getWorldDirection(forward);
  const target = camera.position.clone().addScaledVector(forward, Math.max(1e-3, distance));
  return createCameraPose(
    { x: camera.position.x, y: camera.position.y, z: camera.position.z },
    { x: target.x, y: target.y, z: target.z },
    camera.fov,
  );
}
